import React, { useState, useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker,Polyline, Popup, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import VehicleIcon from './VehicleIcon';
import StationIcon from './StationIcon';

const MapClickHandler = ({ onMapClick }) => {
  useMapEvents({
    click: (e) => {
      if (e && e.latlng) {
        const { lat, lng } = e.latlng;
        onMapClick({ lat, lng });
      } else {
        console.error("LatLng is undefined", e);
      }
    },
  });
  return null;
};

const getOffset = (index) => {
  const offset = 0.0002; // Adjust this value for better spacing
  return {
    lat: (index % 10) * offset,
    lng: Math.floor(index / 10) * offset
  };
};

const interpolatePosition = (start, end, fraction) => {
  return {
    lat: start.lat + (end.lat - start.lat) * fraction,
    lng: start.lng + (end.lng - start.lng) * fraction
  };
};

const animateVehicle = (start, end, duration, updatePosition) => {
  const startTime = performance.now();

  function step(currentTime) {
    const elapsed = currentTime - startTime;
    const fraction = Math.min(elapsed / duration, 1);
    const position = interpolatePosition(start, end, fraction);

    updatePosition(position);

    if (fraction < 1) {
      requestAnimationFrame(step);
    }
  }

  requestAnimationFrame(step);
};

const getVehicleColor = (id) => {
  const colors = [
    'blue',    // 0
    'red',     // 1
    'green',   // 2
    'purple',  // 3
    'orange',  // 4
    'cyan',    // 5
    'magenta', // 6
    'brown',   // 7
    'pink',    // 8
    'yellow'   // 9
  ];
  return colors[id % colors.length]; // Associe une couleur basée sur l'ID du véhicule
};

const MapComponent = React.memo(({ vehicles, stations, steps, onMapClick }) => {
  const [vehiclePositions, setVehiclePositions] = useState({});
  let currentStepIndex = 0;
  useEffect(() => {
    // Initialise les positions des véhicules avec les dates de début et de fin des étapes
    const initialPositions = vehicles.reduce((acc, vehicle) => {
      const vehicleSteps = steps.filter(step => step.vehicleId === vehicle.id);
      const initialStep = vehicleSteps[0];
      acc[vehicle.id] = {
        current: vehicle.previousLocation,
        start: vehicle.previousLocation,
        end: vehicle.location,
        currentStepIndex: 0,
        startTime: new Date(vehicleSteps[currentStepIndex].start_time).getTime(),
        endTime: new Date(vehicleSteps[currentStepIndex].end_time).getTime(),
        color: getVehicleColor(vehicle.id)
      };
      return acc;
    }, {});

    setVehiclePositions(initialPositions);

    const updateVehiclePositions = () => {
      setVehiclePositions((prevPositions) => {
        const newPositions = {};
        const currentTime = Date.now();

        for (let id in prevPositions) {
          const { current, vehicleSteps, currentStepIndex, color } = prevPositions[id];
          const step = vehicleSteps[currentStepIndex];

          if (!step || !step.start || !step.end) {
            continue;
          }

          const progress = Math.min(Math.max((currentTime - step.startTime) / (step.endTime - step.startTime), 0), 1);
          const newLat = step.start.lat + (step.end.lat - step.start.lat) * progress;
          const newLng = step.start.lng + (step.end.lng - step.start.lng) * progress;

          let newStepIndex = currentStepIndex;

          if (progress === 1) {
            // Passer à l'étape suivante si l'actuelle est terminée
            if (currentStepIndex < steps.length - 1) {
              newStepIndex += 1;
            } else {
              // Si c'est la dernière étape, restez à la destination finale
              newStepIndex = currentStepIndex;
            }
          }

          newPositions[id] = {
            current: { lat: newLat, lng: newLng },
            currentStepIndex: newStepIndex,
            color: color
          };
        }

        return newPositions;
      });
    };

    // Mettre à jour les positions des véhicules à des intervalles réguliers
    const intervalId = setInterval(updateVehiclePositions, 100); // Ajustez l'intervalle pour contrôler la fluidité du mouvement

    // Nettoyer l'intervalle à la fin
    return () => clearInterval(intervalId);
  }, [vehicles]);

  // Styles pour les lignes
  const lineStyle = (color) => ({
    color: color,
    weight: 5,
    opacity: 0.7
  });

  return (
    <MapContainer center={[-37.814, 144.96332]} zoom={13} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
      />
      <MapClickHandler onMapClick={onMapClick} />
      {vehicles.map((vehicle, index) => {
        const offset = getOffset(index);
        const position = vehiclePositions[vehicle.id]?.current || vehicle.location;
        return (
          <Marker key={vehicle.id} position={[position.lat, position.lng]} icon={VehicleIcon}>
            <Popup>
              <div>
                <h3>{vehicle.name}</h3>
                <p>Capacity: {vehicle.battery_capacity}</p>
                <p>Battery: {vehicle.battery}</p>
                <p>Consumption: {vehicle.consumption}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {stations.map((station, index) => {
        const offset = getOffset(index + vehicles.length);
        const position = [station.location.lat + offset.lat, station.location.lng + offset.lng];
        return (
          <Marker key={station.id} position={position} icon={StationIcon}>
            <Popup>
              <div>
                <h3>{station.name}</h3>
                <p>Price per kwh: {station.price_per_kwh}</p>
                <p>Charging speed: {station.charging_speed}</p>
                <p>Buy price per kwh: {station.buy_price_per_kwh}</p>
                <p>Discharging speed: {station.discharging_speed}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
    </MapContainer>
  );
});

export default MapComponent;
